import{_ as s,l as o,o as e,c as l,v as t,p as n,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"大页对 TLB 覆盖","description":"","frontmatter":{"title":"大页对 TLB 覆盖","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hugepage-tlb-reach.md","filePath":"cs/hugepage-tlb-reach.md","lastUpdated":1789023840000}'),h={name:"cs/hugepage-tlb-reach.md"};function A(B,a,m,E,T,_){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="大页对-tlb-覆盖" tabindex="-1">大页对 TLB 覆盖 <a class="header-anchor" href="#大页对-tlb-覆盖" aria-label="Permalink to &quot;大页对 TLB 覆盖&quot;">​</a></h1><div class="epigraph"><p>一项 2MiB 映射等于 512 个 4KiB 项；TLB miss 与 PWC 压力一起下降，但内部碎片和预留代价交给 OS。</p><footer>—— 据 Navarro et al., Practical, Transparent Operating System Support for Superpages, OSDI 2002；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/tlb-hierarchy-pwc">上一课</a> 用更多项和 PWC 扩大翻译覆盖。项数受面积限制。本课不重画四级 walk。缺口是<strong>大页（superpage / hugepage）：增大页大小，让同一 TLB 几何覆盖数兆字节到数吉字节。</strong> 顺带放宽 <a href="/cs/vipt-cache">VIPT</a> 的索引约束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据库、JVM、科学数组的工作集远大于 L2 TLB × 4KiB。于是大量时间花在 walk 上，<a href="/cs/cpi-amdahl">CPI</a> 的翻译项显形。缺口不是再加 4 倍 TLB 项，而是<strong>让一项代表连续对齐的大物理区</strong>。OS 必须找到连续物理内存并维护拆页/合并。</p><p><span class="marginnote">RISC-V Sv39 有 2MiB、1GiB 叶。x86 有 2MiB/1GiB。透明大页（THP）尝试在运行时提升，失败则保持 4KiB。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件：TLB 项带页大小字段，比较时掩码 VA 低位。同时查找多种大小（分裂阵列或并行 CAM）。缺失 walk 在叶上发现大页则填大项。I/D 与 ASID 规则同小页。</p>',8)),(e(),n(d,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA%5B%22VA%22%5D%20--%3E%20LKP%5B%22%E6%8C%89%E5%A4%9A%E7%A7%8D%E9%A1%B5%E5%A4%A7%E5%B0%8F%E6%9F%A5%20TLB%22%5D%0A%20%20LKP%20--%3E%7C%22%E5%A4%A7%E9%A1%B5%E5%91%BD%E4%B8%AD%22%7C%20PA%5B%22%E5%B0%91%E9%A1%B9%E8%A6%86%E7%9B%96%E5%A4%A7%E5%8C%BA%22%5D%0A%20%20MISS%5B%22%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20WALK%5B%22walk%20%E9%81%87%E5%A4%A7%E5%8F%B6%E5%88%99%E5%A1%AB%E5%A4%A7%E9%A1%B9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>覆盖：512× 或 262144× 的数量级变化。VIPT：页内位移变长，L1 可以在不引入 <a href="/cs/cache-aliasing">别名</a> 的前提下做得更大。代价：写保护、COW、NUMA 迁移要以大页为粒度，细粒度保护变难；内部碎片浪费 DRAM。预取与 <a href="/cs/line-size-sector">行大小</a> 仍按 cache 行，大页不改变 64B 传输。</p><p>混合大小：L1 TLB 常把 4KiB 与 2MiB 分阵列并行查，避免一种大小的 CAM 把另一种挤掉。1GiB 项很少，多在 L2 TLB。拆页（promoted 页被写保护切碎）会瞬间把覆盖吐回去，PMU 上表现为 TLB miss 尖峰。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Linux <code>mmap</code>/<code>madvise</code> 写成教程。也不保证大页降低一致性流量——假共享仍按 cache 行。下一课回到多核副本：MESI 不够用时引入 Owned 与转发。</p><p>后课默认：翻译覆盖可用大页指数级放大。一致性协议的状态机下一课从 MESI 加 O/F。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>大页用一项覆盖连续大区，TLB/PWC 压力下降。</li><li>OS 负责连续物理页与碎片；硬件负责多大小查找。</li><li>MESI 之上的 Owned/Forward 是下一课。</li><li>出处：Navarro et al., <em>OSDI</em>, 2002；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const S=s(h,[["render",A]]);export{P as __pageData,S as default};
